using System;

namespace StdbModule;

public static partial class ArabicQuotes
{
    public static class ابنخلدون
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "اتباع التقاليد لا يعني أن الأموات أحياء، بل أن الأحياء أموات.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "الظلم مؤذن بخراب العمران.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "الماضي أشبه بالآتيَ من الماء بالماء.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "المغلوب مولع دائماً بتقليد الغالب.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "إن التاريخ في ظاهره لا يزيد عن الإخبار، ولكن في باطنه نظر وتحقيق.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "عوائد كل جيل تابعة لعوائد سلطانه.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "قد لا يتم وجود الخير الكثير إلا بوجود شر يسير.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "يوزن المرء بقوله، ويقوّم بفعله.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "للبقاع تأثير على الطباع، فكلما كانت البقعة من الأرض ندية مزهرة أثرت على طبع ساكنيها بالرقة.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "المُلك إذا كان قاهراً باطشاً منقّباً عن عورات الناس وتعديد ذنوبهم شملهم الخوف والذل، وربّما خذلوه في مواطن الحروب.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "الظفر في الحروب إنما يقع بأمور نفسانية وهمية، وإن كان السلاح والقتال كفيلاً به، لذلك كان الخداع من أنفع ما يستعمل في الحرب ويُظفر به.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "المغلوب مولع بمحاكاة الغالب، لأنّ الهزيمة توحي إليه أنّ مشابهة الغالب قوّة يدفع بها مهانة الضعف الذي جنى عليه تلك الهزيمة.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "النَّاسُ في السَّكينةِ سَواء، فإن جَاءتِ المِحَنُ تَبايَنُوا.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "قد يحصل أنّ الدولة تأخذ بمظاهر القوة والبطش لكنّها إفاقة قريبة الخمود، أشبه بالسراج عند انتهاء الزيت منه، فإنّه يتوهّج لكن سرعان ما ينطفئ.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "الدولة إذا دخلت في سنّ اليأس لا تعود لشبابها أبداً ولو حاول حكامها التغيير، فلكلّ زمان دولة ورجال.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "عندما تنهار الدول يكثر المنجّمون والأفّاكون والمتفيهقون والانتهازيون وتعمّ الإشاعة وتطول المناظرات وتقصر البصيرة ويتشوّش الفكر.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "أهل البدو أقرب إلى الشجاعة من أهل الحضر، والسبب في ذلك أن أهل الحضر ألقوا جنوبهم على مهاد الراحة والدعة وانغمسوا في النعيم والترف ووكلوا أمرهم في المدافعة عن أموالهم وأنفسهم إلى واليهم.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "الشعوب المقهورة تسوء أخلاقها.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "الحاكم الظالم يظهر له الشعب الولاء ويبطن له الكره والبغضاء، فإذا نزلت به نازلة أسلموه ولا يبالون.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "إذا تأذّن الله بانقراض الملك من أمّة حملهم على ارتكاب المذمومات وانتحال الرذائل وسلوك طريقها، وهذا ما حدث في الأندلس وأدّى فيما أدّى إلى ضياعه.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "إذا رأيت الدول تنقص من أطرافها، وحكّامها يكنزون الأموال فدقّ ناقوس الخطر.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "كلّ أمر تُحمل عليه الكافة فلا بُد له من العصبية (القبيلة والنصرة) ففي الحديث ما بعث الله نبياً إلا في مَنَعة من قومه.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "إنَّ أيّام الأمنِ وأيام الرَّغد تمضي سريعاً، وأيّام الجوعِ وأيّام الحروبِ والفتن تكون طويلة.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "انتشار الفساد يدفع بعامّة الشعب إلى مهاوي الفقر والعجز عن تأمين مقتضيات العيش، وبداية لشرخ يؤدّي إلى انهيار الدولة.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "غاية العمران هي الحضارة والترف، وإنه إذا بلغ غايته انقلب إلى الفساد وأخذ في الهرم، كالأعمار الطبيعية للحيوانات.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "من أهمّ شروط العمران سدّ حاجة العيش والأمن {أطعمهم من جوع وآمنهم من خوف}.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "الظلم لا يقع إلا من أهل القدرة والسلطان.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "إذا عمّ الفساد في الدولة فإنّ أولى مراحل الإصلاح في الدولة هي الفوضى.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "كلما فقد الناس ثقتهم بالقضاء تزداد حالة الفوضى، وهي أولى علامات الإصلاح، فالقضاء هو عقل الشعب ومتى فقدوه فقدوا عقولهم.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "السلطان والأمراء لا يتركون غنيّاً في البلاد إلا وزاحموه في ماله وأملاكه، مستظلّين بحكم سلطاني جائر من صنعتهم.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "لا تستقيم رعيّة في حالة كفر أو إيمان بلا عدل قائم أو ترتيب للأمور يشبه العدل.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "العدل إذا دام عمّر، والظلم إذا دام دمّر.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "إن النفس إذا كانت على حال الاعتدال في قبول الخبر أعطته حقه من التمحيص والنظر حتى تبين صدقه من كذبه، وإذا خامرها تشيع لرأي أو نحلة قبلت ما يوافقها من الأخبار لأول وهلة، وكان ذلك الميل والتشيع غطاء على عين بصيرتها عن الانتقاد والتمحيص، فتقع في قبول الكذب ونقله.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "اعلم أن فن التاريخ فن عزيز المذهب جم الفوائد شريف الغاية إذ هو يوقفنا على أحوال الماضين من الأمم في أخلاقهم. والأنبياء في سيرهم. والملوك في دولهم وسياستهم. حتى تتم فائدة الإقتداء.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "أن الاجتماع الانساني ضروري فـالانسان مدني بالطبع أي لا بد له من الاجتماع الذي هو المدنية . ومن العجز عن استكمال وجوده وحياته، فهو محتاج إلى المعاونة في جميع حاجاته أبدا بطبعه.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "العصبية نزعة طبيعية في البشر مذ كانوا.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "ومن هذا الباب الولاء والحلف إذ نصرة كل أحد من أحد على أهل ولائه وحلفه للألفة التي تلحق النفس في اهتضام جارها أو قريبها أو نسيبها بوجه من وجوه النسب ، وذلك لأجل اللحمة الحاصلة من الولاء.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "الغاية التي تجري إليها العصبية هي الملك.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "ذلك أن الرئاسة لا تكون إلا بالغلب والغلب إنما يكون بالعصبية كما قدمناه فلا بد في الرئاسة على القوم أن تكون من عصبية غالبة لعصبياتهم واحدة واحدة.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "أن من عوائق الملك حصول الترف وانغماس القبيل في النعيم.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "أن من عوائق الملك المذلة للقبيل والانقياد إلى سواهم.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "أن الملك إذا ذهب عن بعض الشعوب من أمة فلا بد من عوده إلى شعب آخر منها ما دامت لهم العصبية.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "أن الأمة إذا غلبت وصارت في ملك غيرها أسرع إليها الفناء والسبب في ذلك والله أعلم ما يحصل في النفوس من التكاسل إذا ملك أمرها عليها وصارت بالاستعباد آلة لسواها وعالة عليهم فيقصر الأمل ويضعف التناسل والاعتمار إنما هو عن جدة الأمل.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "أن الدولة لها أعمار طبيعية كما للأشخاص .إعلم أن العمر الطبيعي للأشخاص على ما زعم الأطباء والمنجمون مائة وعشرون سنةً.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "فاز المتملقون.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "المغلوب مولع أبداً بالاقتداء بالغالب في شعاره وزيه ونحلته وسائر أحواله وعوائده والسبب في ذلك أن النفس أبداً تعتقد الكمال في من غلبها وانقادت إليه إما لنظره بالكمال.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "النوع الإنساني لا يتم وجوده الا بالتعاون.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "إعلم أن الله سبحانه ركب في طبائع البشر الخير والشر كما قال تعالى وهديناه النجدين وقال فألهمها فجورها وتقواها والشر أقرب الخلال إليه إذا أهمل في مرعى عوائده ولم يهذبه الاقتداء بالدين وعلى ذلك الجم الغفير إلا من وفقه الله.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "في الأوطان الكثيرة القبائل والعصائب قل أن تستحكم فيها دولة.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "إن العرب لا يتغلبون إلا على البسائط.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "العرب إذا تغلّبوا على أوطان أسرع إليها الخراب.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "إن العرب لا يحصل لهم الملك إلا بصبغة دينية من نبوة ، أو ولاية ، أو أثر عظيم من الدين على الجملة، بسبب خلق التوحش الذي فيهم ،و هم أصعب الأمم انقيادا بعضهم لبعض ، للغلظة والأنفة وبعد الهمة ، والمنافسة في الرياسة ، فقلما تجتمع أهواؤهم.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "أن العرب أبعد الأمم عن سياسة الملك والسبب في ذلك أنهم أكثر بداوة من سائر الأمم وأبعد مجالاً في القفر وأغنى عن حاجات التلول وحبوبها لاعتيادهم لشظف وخشونة العيش فاستغنوا عن غيرهم فصعب انقياد بعضهم لبعض لإفلاهم ذلك.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "البوادي من القبائل والعصائب مغلوبون لأهل الأمصار.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "تطابق الفكر مع نفسه قد يؤدي إلى نتائج تتنافى مع الواقع لأن الصدق في الإستدلال الإستنتاجي مرهون باتساق النتائج مع المقدمات وليس مع الواقع وكل قول بالتطابق مع الواقع بعد تعسف.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "العربي بغير الإسلام لا يساوى قلامة ظفر.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "أن اختلاف الأجيال في أحوالهم انما هو باختلاف نحلهم من المعاش.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "وأما الفلاحة والصناعة والتجارة فهي وجوه طبيعية للمعاش .أما الفلاحة فهي متقدمة عليها كلها بالذات..و أما الصناعة فهي ثانيها ومتأخرة عنها لأنها مركبة وعلمية تصرف فيها الأفكارو الأنظار ، ولهذا لا توجد غالبا إلا في أهل الحضر الذي هو متأخر عن البدو وثان عنه.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "ومنها تقرب الناس في الأكثر لأصحاب التجلة والمراتب بالثناء والمدح وتحسين الأحوال وإشاعة الذكر بذلك فيستفيض الإخبار بها على غير حقيقة فالنفوس مولعة بحب الثناء والناس متطلعون إلى الدنيا وأسبابها من جاه أو ثروة وليسوا في الأكثر براغبين في الفصائل ولا متنافسين في أهلها.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "في المعتدل من الأقاليم والمنحرف وتأثير الهواء في ألوان البشر والكثير في أحوالهم.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "اختلاف أحوال العمران في الخصب والجوع وما ينشأ عن ذلك من الآثار في أبدان البشر وأخلاقهم.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "أن البدو أقدم من الحضر وسابق عليه وأن البادية أصل العمران والأمصار مدد لها.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "في أن أهل البدو أقرب إلى الخير من أهل الحضر وسببه أن النفس إذا كانت على الفطرة الأولى كانت متهيئة لقبول ما يرد.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "أن الهرم إذا نزل بالدولة لا يرتفع.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "اتساع الدولة أولا إلى نهايته ثم تضايقه طورا بعد طور إلى فناء الدولة واضمحلالها.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "اعلم أنّ العدوان على الناس في أموالهم, ذاهبٌ بآمالهم في تحصيلها واكتسابها, لما يرون حينئذٍ من أنّ غايتها ومصيرها انتهابها من أيديهم, وإذا ذهبت آمالهم في اكتسابها وتحصيلها, انقبضت أيديهم عن السعي في ذلك، والعمران ووفوره ونفاق أسواقه.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "اتباع التقاليد لا يعني أن الأموات أحياء، بل أن الأحياء أموات.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "إعلم أنَّ فنَّ التاريخ فن عزيز المذهب، جم الفوائد، شريف الغاية إذ هو يوقفنا على أحوال الماضين من الأمم في أخلاقهم، والأنبياء في سيرهمْ، والملوك في دولهم وسياستهمْ، حتى تتمَّ فائدةُ الاقتداء في ذلك لمن يرومه في أحوال الدين والدنيا.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "إنّ القبيلة إذا قوي سلطانها ضعف سلطان الدولة، وإذا قوي سلطان الدولة ضعف سلطان القبيلة.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "الاستبداد يقلب موازين الأخلاق، فيجعل من الفضائل رذائل، ومن الرذائل فضائل.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "الظلم مخرّب للعمران، وإنّ عائدة الخراب في العمران على الدولة بالفساد والانتقاض.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "دخول الحكام والأمراء للسوق والتجارة والفلاحة مضرّة عاجلة للرعايا وفساد للجباية ونقص للعمارة.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "السيف والقلم أداة بيد الحاكم يستعين بهما على أمره والحاجة إلى السيف في نشأة الدولة وهرمها أكثر من الحاجة للقلم.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "الُملك بالجند، والجند بالمال، والمال بالخراج، والخراج بالعمارة، والعمارة بالعدل، والعدل بإصلاح العمّال، وإصلاح العمّال باستقامة الوزراء.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "الهوية القبلية المبنية على البداوة تعرقل استقرار الدولة.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "إذا خشي الناس أن يسلب الظلم حقوقهم أحبّوا العدل وتغنّوا بفضائله، فإذا أمنوا وكانت لهم القوّة التي يظلمون بها تركوا العدل.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "الخوف يُحي النزعات القبلية والمناطقية والطائفية، والأمن والعدل يلغيها.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "إن الرخاء والازدهار والأمن تساهم في الحدّ من العصبية، بينما الحروب والخوف والفقر (البطالة) تعزّز من العصبية.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "إذا زال العدل انهارت العمارة وتوقف الإنتاج، فافتقر الناس واستمرّت سلسلة التساقط حتى زوال الملك.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "الترف مفسد للخلق، مضعف للهمة.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "االعلوم الطبيعية لا تحصل إلا بالخبرة والتجربة.", Author = "ابن خلدون" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/ابن_خلدون", Text = "النفس إذا ألفت شيئا ً صار من جبلتها وطبيعتها ...لأنها كثيرة التلون.", Author = "ابن خلدون" },
        };
    }
}